import axios from "axios";

const url = 'http://localhost:8000/api';

export function signIn(username, password){
    try{
        return axios.post(`${url}/signin`,{username, password})
    }catch (error){
        console.error("Sign in error:", error);
        throw error.response ? error.response.data : error;
    }
}

export function register (username, password){
    try{
        return axios.post(`${url}/register`,{username, password})
    }catch (error){
        console.error("Sign up error:", error);
        throw error.response ? error.response.data : error;
    }
}

export function forgetPassword(username){
    try {
        return axios.post(`${url}/forgetpassword`,
            {username : username}
        )
    }catch (error){
        console.error("Sign up error:", error);
        throw error.response ? error.response.data : error;
    }
}

export function resetPassword(password, token){
    try{
        return axios.post(`${url}/resetpassword`,
            {password : password},
            {
                    headers: {
                        Authorization: `Bearer ${token}`
                    }
                }
            )
    }catch (error){
        console.error("Sign up error:", error);
        throw error.response ? error.response.data : error;
    }
}
